import React, { useState } from 'react';
import { ArrowRight, ArrowLeft } from 'lucide-react';
import { useNavigate, useLocation } from 'react-router-dom';
import Header from '../components/Header';
import '../styles/OnboardingPage.css';

export default function OnboardingPage() {
  const navigate = useNavigate();
  const location = useLocation();
  const studentName = location.state?.fullName || 'Student';
  const userId = location.state?.userId;

  const [step, setStep] = useState('welcome'); // 'welcome' | 'step1_purpose' | 'step2_role' | 'complete'
  const [selectedReason, setSelectedReason] = useState(''); // Single selection for purpose
  const [selectedRole, setSelectedRole] = useState(''); // Single selection for role
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [showAlert, setShowAlert] = useState(false);
  const [alertMessage, setAlertMessage] = useState('');

  const reasons = [
    { id: 'start_career', label: 'Start my career' },
    { id: 'grow_career', label: 'Grow in my career' },
    { id: 'change_career', label: 'Change my career' },
    { id: 'gain_knowledge', label: 'Gain my knowledge' }
  ];

  const roles = [
    { id: 'writer', label: 'Writer' },
    { id: 'ba', label: 'BA' },
    { id: 'se', label: 'SE' },
    { id: 'cio', label: 'CIO' }
  ];

  const handleReasonToggle = (id) => {
    setSelectedReason(id); // Single selection
  };

  const handleStartClick = () => {
    setStep('questions');
  };

  const handleBack = () => {
    navigate('/login');
  };

  const handleNext = async () => {
    if (!selectedReason) {
      setAlertMessage('Please select a purpose');
      setShowAlert(true);
      return;
    }

    if (!userId) {
      setError('User ID not found. Please sign up again.');
      return;
    }

    setIsLoading(true);
    setError('');
    try {
      const response = await fetch('http://localhost:5102/api/onboarding/save-journey-reasons', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          userId: userId,
          selectedReasons: [selectedReason], // Send as array for backend compatibility
        }),
      });

      const data = await response.json();

      if (data.success) {
        console.log('Journey reasons saved:', data);
        setStep('complete');
        // Navigate to dashboard after a brief delay
        setTimeout(() => {
          navigate('/dashboard', { state: { userId, selectedReason } });
        }, 500);
      } else {
        setError(data.message || 'Failed to save journey reasons');
      }
    } catch (err) {
      console.error('Error saving journey reasons:', err);
      setError('Failed to connect to server. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="onboarding-page">
      {/* Header */}
      <Header />

      {/* Main Content */}
      <div className="onboarding-container">
        <div className="onboarding-card">
          {/* Back Button */}
          <button className="back-btn" onClick={handleBack} title="Go back to login">
            <ArrowLeft size={24} />
          </button>
          {/* STEP 1: Welcome Screen */}
          {step === 'welcome' && (
            <>
              {/* Welcome Section */}
              <div className="onboarding-welcome">
                <h1 className="onboarding-greeting">Hello {studentName}!</h1>
                <div className="onboarding-bus-title">
                  <span className="bus-icon">🚐</span>
                  <p className="onboarding-subtitle">Begin the Learning Journey Bus!</p>
                </div>
                <p className="onboarding-intro">Let's get to know who you are!</p>
              </div>

              {/* Step Indicator */}
              <div className="onboarding-step">
                <h2 className="step-label">Step 1</h2>
              </div>

              {/* Let's Start Button */}
              <div className="onboarding-footer">
                <button
                  className="onboarding-start-btn"
                  onClick={handleStartClick}
                >
                  <span>Let's Start</span>
                  <ArrowRight size={20} />
                </button>
              </div>
            </>
          )}

          {/* STEP 2: Questions Screen */}
          {step === 'questions' && (
            <>
              {/* Questions Section */}
              <div className="onboarding-questions">
                <div className="question-group">
                  <p className="question-text">Why do you choose Learnix?</p>
                  <p className="question-subtext">Why are you here?</p>
                </div>

                {/* Radio Button Options */}
                <div className="reasons-list">
                  {reasons.map(reason => (
                    <label key={reason.id} className="reason-item">
                      <input
                        type="radio"
                        name="purpose"
                        value={reason.id}
                        checked={selectedReason === reason.id}
                        onChange={() => handleReasonToggle(reason.id)}
                        className="reason-radio"
                      />
                      <span className="reason-label">{reason.label}</span>
                    </label>
                  ))}
                </div>
              </div>

              {/* Next Button */}
              <div className="onboarding-footer">
                {error && <div className="error-message">{error}</div>}
                <button
                  className="onboarding-next-btn"
                  onClick={handleNext}
                  disabled={isLoading}
                >
                  <span>{isLoading ? 'Saving...' : 'Next'}</span>
                  {!isLoading && <ArrowRight size={20} />}
                </button>
              </div>
            </>
          )}
        </div>
      </div>

      {/* Alert Popup */}
      {showAlert && (
        <div className="alert-overlay">
          <div className="alert-popup">
            <div className="alert-content">
              <p className="alert-message">{alertMessage}</p>
              <button
                className="alert-btn"
                onClick={() => setShowAlert(false)}
              >
                OK
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
